  1	/**
  2	 * Read-only client for the project workflow viewer API (`contracts/projects/README.md`).
  3	 *
  4	 * Every payload is validated against the committed contract schemas before it reaches a component. A
  5	 * response that fails validation is a malformed-payload error: nothing is patched up or substituted.
  6	 * Artifacts and results are only ever requested through the scoped routes of the run being viewed.
  7	 */
  8	import { z } from 'zod'
  9	import {
 10	  isBlockingFinding,
 11	  schemas,
 12	  validateReviewResult,
 13	  validateRunDetail,
 14	  validateRunInputs,
 15	  type Project,
 16	  type ReviewFinding,
 17	  type ReviewResult,
 18	  type RunDetail,
 19	  type RunInputs,
 20	  type RunInputWorker,
 21	  type RunSummary,
 22	  type WorkflowDefinition,
 23	} from '../../contracts/projects/v1.ts'
 24	import { eventSchema, validateWorkerResult, type WorkerResult, type WorkflowEvent } from '../../contracts/workflow/v1.ts'
 25	
 26	export type { Project, ReviewFinding, ReviewResult, RunDetail, RunInputs, RunInputWorker, RunSummary, WorkflowDefinition, WorkerResult, WorkflowEvent }
 27	export { isBlockingFinding }
