 29	/** The contract's "not recorded" 404 codes: a run whose export predates a section, never an error state. */
 30	export const NOT_RECORDED = { review: 'REVIEW_NOT_FOUND', inputs: 'INPUTS_NOT_FOUND' } as const
 31	
 32	export type ApiErrorKind = 'network' | 'http' | 'malformed'
 33	
 34	/** A failed request. `status` is set for HTTP failures; `code` comes from the contract error body when present. */
 35	export class ProjectsApiError extends Error {
 36	  readonly kind: ApiErrorKind
 37	  readonly status: number | null
 38	  readonly code: string | null
 39	  readonly path: string
 40	
 41	  constructor(kind: ApiErrorKind, message: string, path: string, options: { status?: number | null; code?: string | null } = {}) {
 42	    super(message)
 43	    this.name = 'ProjectsApiError'
 44	    this.kind = kind
 45	    this.status = options.status ?? null
 46	    this.code = options.code ?? null
 47	    this.path = path
 48	  }
 49	
 50	  get notFound(): boolean {
 51	    return this.kind === 'http' && this.status === 404
 52	  }
 53	}
 54	
 55	export function describeApiError(error: unknown): string {
 56	  if (error instanceof ProjectsApiError) {
 57	    switch (error.kind) {
 58	      case 'network': return 'The API could not be reached. Check that the server is running, then retry.'
 59	      case 'malformed': return `The API returned data that does not match the projects contract: ${error.message}`
 60	      case 'http': return error.code ? `${error.message} (${error.code}, HTTP ${error.status})` : `${error.message} (HTTP ${error.status})`
 61	    }
 62	  }
 63	  return error instanceof Error && error.message ? error.message : 'An unexpected error occurred.'
 64	}
 65	
 66	const errorBodySchema = z.object({ error: z.object({ code: z.string(), message: z.string() }) })
 67	
 68	function encodeSegments(...segments: string[]): string {
 69	  return segments.map(encodeURIComponent).join('/')
 70	}
 71	
 72	export type RunScope = { projectId: string; workflowId: string; runId: string }
 73	
 74	export const paths = {
 75	  projects: () => '/api/projects',
 76	  workflows: (projectId: string) => `/api/projects/${encodeSegments(projectId)}/workflows`,
 77	  runs: (projectId: string, workflowId: string, options: { limit?: number; cursor?: string | null } = {}) => {
 78	    const query = new URLSearchParams()
 79	    if (options.limit !== undefined) query.set('limit', String(options.limit))
 80	    if (options.cursor) query.set('cursor', options.cursor)
 81	    const suffix = query.size ? `?${query}` : ''
 82	    return `/api/projects/${encodeSegments(projectId)}/workflows/${encodeSegments(workflowId)}/runs${suffix}`
 83	  },
 84	  run: (scope: RunScope) => `/api/projects/${encodeSegments(scope.projectId)}/workflows/${encodeSegments(scope.workflowId)}/runs/${encodeSegments(scope.runId)}`,
 85	  events: (scope: RunScope, after = 0) => `${paths.run(scope)}/events?after=${after}`,
 86	  result: (scope: RunScope, nodeId: string, attempt: number) => `${paths.run(scope)}/results/${encodeSegments(nodeId)}/${attempt}`,
 87	  artifact: (scope: RunScope, artifactId: string) => `${paths.run(scope)}/artifacts/${encodeSegments(artifactId)}`,
 88	  review: (scope: RunScope, attempt: number) => `${paths.run(scope)}/reviews/${attempt}`,
 89	  inputs: (scope: RunScope) => `${paths.run(scope)}/inputs`,
 90	}
