133	export type RunPage = { runs: RunSummary[]; nextCursor: string | null }
134	
135	export function fetchRuns(projectId: string, workflowId: string, options: { cursor?: string | null } = {}, signal?: AbortSignal): Promise<RunPage> {
136	  return requestJson(paths.runs(projectId, workflowId, options), input => {
137	    const page = schemas.runList.parse(input)
138	    for (const run of page.runs) {
139	      if (run.project_id !== projectId || run.workflow_id !== workflowId) throw new Error(`run ${run.run_id} belongs to another scope.`)
140	    }
141	    return { runs: page.runs, nextCursor: page.next_cursor }
142	  }, signal)
143	}
