155	const eventListSchema = z.strictObject({ events: z.array(eventSchema) })
156	
157	export function fetchEvents(scope: RunScope, signal?: AbortSignal): Promise<WorkflowEvent[]> {
158	  return requestJson(paths.events(scope, 0), input => {
159	    const events = eventListSchema.parse(input).events
160	    // Deduplicate by sequence and keep the persisted order; the run ID must be this run's.
161	    const seen = new Set<number>()
162	    const unique: WorkflowEvent[] = []
163	    for (const event of events) {
164	      if (event.run_id !== scope.runId) throw new Error(`event ${event.event_id} belongs to run ${event.run_id}.`)
165	      if (seen.has(event.sequence)) continue
166	      seen.add(event.sequence)
167	      unique.push(event)
168	    }
169	    return unique.sort((a, b) => a.sequence - b.sequence)
170	  }, signal)
171	}
