173	/** Only results published under this run's scoped `results/` route are fetched; anything else is refused. */
174	export function scopedResultPath(scope: RunScope, resultUri: string): string | null {
175	  const prefix = `${paths.run(scope)}/results/`
176	  if (!resultUri.startsWith(prefix)) return null
177	  const rest = resultUri.slice(prefix.length).split('/')
178	  if (rest.length !== 2 || rest.some(segment => segment === '') || !/^[1-9][0-9]*$/.test(rest[1])) return null
179	  return resultUri
180	}
