 18	/** A failed request: what failed, why, and what the reader can do. Never replaced by sample data. */
 19	export function ErrorPanel({ error, what, onRetry, children }: { error: unknown; what: string; onRetry?: () => void; children?: ReactNode }) {
 20	  const api = error instanceof ProjectsApiError ? error : null
 21	  return (
 22	    <div className="projects-error" role="alert" data-testid="projects-error" data-error-kind={api?.kind ?? 'unknown'}>
 23	      <p><strong>{what} could not be loaded.</strong> {describeApiError(error)}</p>
 24	      {api?.kind === 'http' && api.status !== null && api.status >= 500 && <p>The server reported a failure; nothing was substituted for the missing data. Retry once it has recovered.</p>}
 25	      {api?.kind === 'malformed' && <p>The response was rejected rather than rendered, because it might be incomplete or from an incompatible server version.</p>}
 26	      {api && <p className="projects-error-path">Request: <code>{api.path}</code></p>}
 27	      <div className="projects-actions">
 28	        {onRetry && <button type="button" className="button" onClick={onRetry}>Retry</button>}
 29	        {children}
 30	      </div>
 31	    </div>
 32	  )
 33	}
