 51	/** A link that navigates inside the app through history rather than reloading. Other anchor attributes (title, data-*) pass through. */
 52	export function AppLink({ href, onNavigate, className, children, current = false, ...rest }: AppLinkProps) {
 53	  return (
 54	    <a
 55	      {...rest}
 56	      href={href}
 57	      className={className}
 58	      aria-current={current ? 'page' : undefined}
 59	      onClick={event => {
 60	        if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey || event.button !== 0) return
 61	        event.preventDefault()
 62	        onNavigate(href)
 63	      }}
 64	    >
 65	      {children}
 66	    </a>
 67	  )
 68	}
 69	/**
 70	 * Human wording for run and node states. The wording deliberately separates "this node finished" from
 71	 * "this workflow is complete": only a `succeeded` run is complete, and a worker node's success only means
 72	 * its native session launched and ended its turn.
 73	 */
 74	import { isBlockingFinding, type ReviewResult, type RunDetail } from './api.ts'
 75	
 76	export type RunStatus = RunDetail['summary']['status']
 77	export type NodeKind = RunDetail['definition']['nodes'][number]['kind']
