 89	/** What a run in this status means for the workflow as a whole. */
 90	export const RUN_STATUS_MEANING: Record<RunStatus, string> = {
 91	  pending: 'Nothing has started yet.',
 92	  running: 'Work is in progress. The workflow is not complete.',
 93	  awaiting_approval: 'Stopped at a decision that has not been made. The workflow is not complete; nothing is approved by viewing it.',
 94	  paused: 'Paused with unresolved state (for example a session that could not be reconciled). The workflow is not complete.',
 95	  succeeded: 'Integration was confirmed and no graph work remains.',
 96	  failed: 'A graph step or check failed. The workflow did not complete.',
 97	  cancelled: 'The run was cancelled before completion.',
 98	}
