100	/** What a node in this status means, given its kind. */
101	export function nodeStatusMeaning(kind: NodeKind, status: RunStatus): string {
102	  switch (status) {
103	    case 'pending': return 'Not started: no attempt has run.'
104	    case 'running': return kind === 'worker' ? 'The native worker session is running or its turn has not been signalled complete.' : 'In progress.'
105	    case 'awaiting_approval': return 'Waiting for an explicit decision recorded outside this viewer. Not complete.'
106	    case 'paused': return 'Paused with unresolved evidence. Not complete.'
107	    case 'succeeded':
108	      return kind === 'worker'
109	        ? 'The worker session launched and ended its turn. This is not workflow completion; verification, review and integration are separate nodes.'
110	        : kind === 'integration'
111	          ? 'This integration step completed.'
112	          : 'This step completed.'
113	    case 'failed': return 'This step failed. The run cannot succeed without intervention.'
114	    case 'cancelled': return 'This step was cancelled.'
115	  }
116	}
