130	export function formatTime(iso: string): string {
131	  const time = Date.parse(iso)
132	  if (Number.isNaN(time)) return iso
133	  return new Date(time).toISOString().replace('T', ' ').replace(/\.\d{3}Z$/, ' UTC')
