136	/** Compact duration for deadlines and timeouts: 14400 → "4h", 5400 → "1h30m", 45 → "45s". */
137	export function formatDuration(seconds: number): string {
138	  const hours = Math.floor(seconds / 3600)
139	  const minutes = Math.floor((seconds % 3600) / 60)
140	  const rest = seconds % 60
141	  const parts: string[] = []
142	  if (hours > 0) parts.push(`${hours}h`)
143	  if (minutes > 0) parts.push(`${minutes}m`)
144	  if (rest > 0 || parts.length === 0) parts.push(`${rest}s`)
145	  return parts.join('')
146	}
