153	const DISPOSITIONS = ['open', 'resolved', 'accepted'] as const
154	
155	/** One line for a recorded review: verdict, finding counts by disposition and how many block integration (unresolved P0/P1). */
156	export function reviewSummary(review: ReviewResult): string {
157	  const { verdict, findings } = review
158	  if (findings.length === 0) return `${verdict} with no findings`
159	  const counts = DISPOSITIONS
160	    .map(disposition => [disposition, findings.filter(finding => finding.disposition === disposition).length] as const)
161	    .filter(([, count]) => count > 0)
162	    .map(([disposition, count]) => `${count} ${disposition}`)
163	  const blocking = findings.filter(isBlockingFinding).length
164	  return `${verdict} with ${findings.length} ${findings.length === 1 ? 'finding' : 'findings'}: ${counts.join(', ')}, ${blocking === 0 ? 'none blocking' : `${blocking} blocking`}`
165	}
166	import { useCallback, useEffect, useRef, useState } from 'react'
167	
168	export type Resource<T> =
169	  | { status: 'idle' }
170	  | { status: 'loading' }
171	  | { status: 'ready'; data: T }
172	  | { status: 'error'; error: unknown }
173	
174	/**
175	 * Loads one read-only resource identified by `key`. A null key means nothing to load. Changing the key or
176	 * calling `reload` starts a fresh request and abandons the previous one; a stale response never wins
177	 * because every settled value is tagged with the request token that produced it.
178	 * `refreshToken` forces a reload without changing the key (the header Refresh button).
179	 */
180	export function useResource<T>(key: string | null, load: (signal: AbortSignal) => Promise<T>, refreshToken = 0): { state: Resource<T>; reload: () => void } {
181	  const [settled, setSettled] = useState<{ token: string; value: Resource<T> } | null>(null)
182	  const [attempt, setAttempt] = useState(0)
183	  const loadRef = useRef(load)
184	  useEffect(() => { loadRef.current = load }, [load])
185	  const token = key === null ? null : `${key}\u0000${attempt}\u0000${refreshToken}`
186	
187	  useEffect(() => {
188	    if (token === null) return
189	    const controller = new AbortController()
190	    loadRef.current(controller.signal).then(
191	      data => { if (!controller.signal.aborted) setSettled({ token, value: { status: 'ready', data } }) },
192	      error => { if (!controller.signal.aborted) setSettled({ token, value: { status: 'error', error } }) },
193	    )
194	    return () => controller.abort()
195	  }, [token])
196	
197	  const reload = useCallback(() => setAttempt(previous => previous + 1), [])
198	  const state: Resource<T> = token === null ? { status: 'idle' } : settled?.token === token ? settled.value : { status: 'loading' }
199	  return { state, reload }
200	}
201	/**
202	 * Projects routes: `/projects[/<project>[/workflows/<workflow>[/runs/<run>[/nodes/<node>]]]]`.
203	 *
204	 * Every ID is an opaque contract identifier: it must match the shared ID pattern and is percent-encoded
205	 * as one path segment. Anything else is malformed rather than looked up. This domain is read-only and
206	 * separate from the Pi/Claude skill sources; nothing here names a filesystem path.
207	 */
208	
209	/** Same pattern as the shared projects contract (`contracts/projects/v1.ts`). */
210	export const PROJECT_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/
211	
212	export const PROJECTS_ROUTE = 'projects'
213	
214	export type ProjectsRoute =
215	  | { level: 'projects' }
216	  | { level: 'project'; projectId: string }
217	  | { level: 'workflow'; projectId: string; workflowId: string }
218	  | { level: 'run'; projectId: string; workflowId: string; runId: string; nodeId: string | null }
219	
220	export function isContractId(value: string): boolean {
221	  return PROJECT_ID_PATTERN.test(value)
222	}
223	
224	function encode(segments: string[]): string {
225	  return `/${segments.map(encodeURIComponent).join('/')}`
226	}
227	
228	export function projectsPathname(): string {
229	  return `/${PROJECTS_ROUTE}`
230	}
231	
232	export function projectPathname(projectId: string): string {
233	  return encode([PROJECTS_ROUTE, projectId])
234	}
235	
236	export function workflowPathname(projectId: string, workflowId: string): string {
237	  return encode([PROJECTS_ROUTE, projectId, 'workflows', workflowId])
238	}
239	
240	export function runPathname(projectId: string, workflowId: string, runId: string, nodeId: string | null = null): string {
241	  const segments = [PROJECTS_ROUTE, projectId, 'workflows', workflowId, 'runs', runId]
242	  if (nodeId !== null) segments.push('nodes', nodeId)
243	  return encode(segments)
244	}
245	
246	export function routeToPathname(route: ProjectsRoute): string {
247	  switch (route.level) {
248	    case 'projects': return projectsPathname()
249	    case 'project': return projectPathname(route.projectId)
250	    case 'workflow': return workflowPathname(route.projectId, route.workflowId)
251	    case 'run': return runPathname(route.projectId, route.workflowId, route.runId, route.nodeId)
252	  }
253	}
254	
255	/** Whether a pathname belongs to the Projects domain at all (decided before any decoding). */
256	export function isProjectsPathname(pathname: string): boolean {
257	  const first = pathname.split('/').filter(segment => segment !== '')[0]
258	  return first === PROJECTS_ROUTE
259	}
260	
261	/**
262	 * Parses a Projects pathname. Returns null when it is not a Projects pathname or when any segment is
263	 * malformed (bad encoding, an invalid ID, an unexpected literal or trailing segments).
264	 */
265	export function parseProjectsPathname(pathname: string): ProjectsRoute | null {
266	  const raw = pathname.split('/').filter(segment => segment !== '')
267	  if (raw[0] !== PROJECTS_ROUTE) return null
268	  let segments: string[]
269	  try {
270	    segments = raw.slice(1).map(decodeURIComponent)
271	  } catch {
272	    return null
273	  }
274	  if (segments.length === 0) return { level: 'projects' }
